using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using KianaPet;
class CompanionTests {
 static int checks;static readonly List<string> names=new List<string>();
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;names.Add(name);}
 static void Reject(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception("Expected rejection: "+name);}
 static object F(object obj,string key){return obj.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);}
 static void Set(object obj,string key,object value){obj.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(obj,value);}
 static object Call(object obj,string name,params object[] args){return obj.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,args);}
 static void Music(){var c=new Config{MusicEntryDelaySeconds=0,MusicNormalAction="quiet",MusicChorusAction="lively"};var s=new MusicState{Connected=true,Playing=true,Id="123",Title="Fixture",Position=10,Duration=200,At=DateTime.UtcNow};var ranges=new[]{new ChorusRange{Start=30,End=50}};Func<string,MusicActivityReport> read=actual=>MusicActivity.Read(c,s,ranges,"暂无区间",actual,"",0,false,DateTime.UtcNow);
  var r=read("music-quiet");Check(r.Action.Contains("坐着")&&r.Chorus.Contains("下段 00:30")&&r.Reason.Contains("尚未进入"),"normal phase and next chorus");s.Position=35;r=read("music-lively");Check(r.Chorus.Contains("副歌中")&&r.Reason.Contains("已按副歌"),"chorus uses actual action");c.MusicChorusAction="same";Check(read("music-quiet").Reason.Contains("相同"),"same actions explain absent transition");c.MusicChorusAction="off";Check(read("idle").Reason.Contains("不做"),"off chorus reason");s.HasPosition=false;r=read("music-quiet");Check(r.Chorus.Contains("无法判断")&&!r.Chorus.Contains("下段")&&r.Reason.Contains("缺少"),"no fabricated chorus when progress absent");s.HasPosition=true;s.At=DateTime.UtcNow.AddSeconds(-10);Check(read("idle").Chorus.Contains("过期"),"stale progress is not interpreted");s.At=DateTime.UtcNow;
  c.MusicChorusEnabled=false;Check(read("music-quiet").Reason.Contains("自动副歌查询已关闭"),"disabled query explains missing intervals");c.MusicSongPreferences=new[]{new SongMusicPreference{Id="123",Start=30,End=50,NormalAction="gentle",ChorusAction="lively"}};Check(read("music-lively").Chorus.Contains("手动"),"manual range works with automatic query off");Check(read("music-lively").Rules.Contains("本曲覆盖"),"song override source visible");c.ReduceMotion=true;Check(read("idle").Reason.Contains("减少动态"),"reduced motion reason");c.ReduceMotion=false;c.Skin="kiana-fiery-wishing-star";Check(read("idle").Reason.Contains("普通版"),"unsupported skin reason");c.Skin="kiana-fiery-wishing-star-round";r=MusicActivity.Read(c,s,ranges,"", "running","GPT 任务优先",0,false,DateTime.UtcNow);Check(r.Action!=MusicReactions.Label("lively")&&r.Reason.Contains("GPT"),"actual priority action reported instead of target");Check(MusicActivity.Read(c,s,ranges,"","idle","",2.2,false,DateTime.UtcNow).Reason.Contains("3 秒"),"initial delay countdown");s.Playing=false;Check(MusicActivity.Read(c,s,ranges,"","music-gentle","",0,true,DateTime.UtcNow).Reason.Contains("保留"),"pause grace explained");
 }
 static void Scenes(){var c=new Config{AutoScenesEnabled=true,Walking=false,MusicHoverOnly=true};var original=PreferenceTransfer.Copy(c);var planner=new SceneAutomation();Check(!planner.Tick(c,"休闲",0)&&!planner.Tick(c,"休闲",1),"scene debounce waits");Check(planner.Tick(c,"休闲",2)&&c.Walking&&!c.MusicHoverOnly,"matching scene applies");var saved=planner.Persistent(c);Check(!saved.Walking&&saved.MusicHoverOnly,"temporary overlay excluded from persistent preferences");c.MusicLyrics=true;planner.Tick(c,"",3);Check(planner.Tick(c,"",5)&&!c.Walking&&c.MusicHoverOnly&&c.MusicLyrics,"leaving scene restores baseline and retains manual edits");planner.Tick(c,"休闲",6);planner.Tick(c,"休闲",8);planner.Pause(c);Check(!c.Walking&&planner.Paused&&!planner.Tick(c,"休闲",20),"manual pause restores and holds");planner.Resume();planner.Tick(c,"游戏",21);Check(planner.Tick(c,"游戏",23)&&!c.MusicEnabled,"automatic switching can resume");c.AutoScenesEnabled=false;Check(planner.Tick(c,"",24)&&c.MusicEnabled,"disabling automatic mode restores baseline");
  c.AutoSceneRules=new[]{new AutoSceneRule{Trigger="foreground",Process="Code.EXE",Scene="工作"},new AutoSceneRule{Trigger="music",Scene="休闲"},new AutoSceneRule{Trigger="time",Scene="游戏",Start="23:00",End="06:00"}};c.Validate();Check(SceneAutomation.Match(c,"code",true,false,TimeSpan.Zero)=="工作","first matching rule wins, case-insensitive process");Check(SceneAutomation.Match(c,"",false,false,TimeSpan.FromHours(1))=="游戏","cross-midnight schedule");c.AutoSceneRules=new[]{new AutoSceneRule{Trigger="music",Scene="游戏"}};Check(SceneAutomation.Match(c,"",true,false,TimeSpan.Zero)=="","music scene cannot disable its own trigger");Check(original.GPTConnectionMode==c.GPTConnectionMode&&original.MusicConnectionMode==c.MusicConnectionMode,"scene changes preserve connection modes");
 }
 static void Focus(){var c=new Config{FocusMinutes=1,BreakMinutes=1};var f=new FocusClock();f.Begin(false,c,0);Check(!f.Tick(10,false)&&f.Session.Remaining==50,"focus counts elapsed time");f.Pause(10);f.Tick(100,false);Check(f.Session.Remaining==50&&!f.Session.Running,"paused time excluded");f.Resume(100);Check(!f.Tick(149,false)&&f.Tick(150,false)&&f.Session.Phase=="break-ready"&&f.Session.Completed==1,"focus completes once and waits for manual break");Check(!f.Tick(300,false),"completion is not duplicated");f.Begin(true,c,300);f.Tick(310,true);Check(!f.Session.Running,"lock pauses timer");var snapshot=Store.Json.Deserialize<FocusSession>(Store.Json.Serialize(f.Session));snapshot.Running=true;f.Load(snapshot);Check(!f.Session.Running&&f.Session.Remaining==60,"restored session remains paused");f.Resume(400);Check(f.Tick(460,false)&&f.Session.Phase=="focus-ready","break does not auto-start next focus");f.Reset();Check(f.Session.Phase=="idle"&&f.Session.Completed==1,"ending round retains completed count");f.Load(new FocusSession{Phase="invalid",Remaining=double.NaN});Check(f.Session.Phase=="idle","invalid persisted timer resets safely");}
 static void Sharing(){string folder=Path.Combine(Store.Root,"shared");Directory.CreateDirectory(folder);string file=Path.Combine(folder,"preferences.json");var c=new Config{Theme="dark",SharedPreferenceFile="E:\\private\\share.json",GPTConnectionMode="hooks",X=123,HasPosition=true,AutoScenesEnabled=true,ExternalNoticesEnabled=true};var first=SharedPreferences.Publish(file,c,null);Check(first.Info.Preferences.Theme=="dark"&&first.Snapshot.Revision.Length>0,"publish and read shared snapshot");Check(!first.Info.PresentKeys.Any(PreferenceReview.Local)&&!first.Snapshot.Package.Contains("private"),"shared snapshot excludes local connection, rules and paths");var local=new Config{Theme="light",GPTConnectionMode="cdp",X=99,HasPosition=true};var merge=PreferenceReview.Merge(local,first.Info,false,false);Check(merge.Theme=="dark"&&merge.X==99&&merge.GPTConnectionMode=="cdp"&&!merge.AutoScenesEnabled&&!merge.ExternalNoticesEnabled,"shared merge protects machine settings");var second=SharedPreferences.Publish(file,new Config{Theme="light"},first.Hash);Reject(()=>SharedPreferences.Publish(file,c,first.Hash),"concurrent shared update is rejected");Check(SharedPreferences.Read(file).Hash==second.Hash,"concurrent rejection preserves winner");File.WriteAllText(file,"{}");Reject(()=>SharedPreferences.Publish(file,c,second.Hash),"invalid shared file is never overwritten");Check(File.ReadAllText(file)=="{}","invalid source stays intact");}
 static void Inbox(){string root=Path.Combine(Store.Root,"inbox-fixture");var hub=new TaskNoticeHub();var inbox=new ExternalTaskInbox(root,hub);DateTime at=DateTime.UtcNow.AddSeconds(-10);ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Training",TaskId="a",Title="done",Status="succeeded",At=at.AddSeconds(1)});ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Training",TaskId="a",Title="running",Status="running",At=at});Check(inbox.Drain()==2&&hub.Snapshot().Single().Status=="succeeded","out-of-order queue resolves newest event");ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Training",TaskId="a",Title="late",Status="running",At=at});Check(inbox.Drain()==0&&hub.Snapshot().Single().Status=="succeeded","late running does not undo terminal state");var restarted=new ExternalTaskInbox(root,new TaskNoticeHub());ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Training",TaskId="a",Title="late",Status="running",At=at});Check(restarted.Drain()==0,"receipts survive receiver restart");Reject(()=>ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="ChatGPT",TaskId="b",Title="fake",Status="succeeded"}),"reserved source rejected");Reject(()=>ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Training",TaskId="b",Title="bad",Status="unknown"}),"unknown external status rejected");Reject(()=>ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Training",TaskId="b",Title="bad",Status="succeeded",OpenPath="https://example.com"}),"URL actions rejected");
  ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Tie",TaskId="same-ms",Title="done",Status="succeeded",At=at,EventId="a"});ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Tie",TaskId="same-ms",Title="running",Status="running",At=at,EventId="z"});inbox.Drain();Check(hub.Snapshot().Single(n=>n.Source=="Tie").Status=="succeeded","terminal state wins equal-millisecond ordering");ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Tie",TaskId="same-ms",Title="late",Status="running",At=at,EventId="zz"});Check(inbox.Drain()==0,"same-millisecond late running cannot undo terminal state");
  string artifact=Path.Combine(root,"output.txt");File.WriteAllText(artifact,"fixture");ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Render",TaskId="output",Title="Exported",Status="succeeded",OpenPath=artifact});Check(inbox.Drain()==1&&hub.CanOpen(hub.Snapshot().First(n=>n.Source=="Render")),"output path registers action without executing it");for(int i=0;i<120;i++)ExternalTaskInbox.Write(root,new ExternalTaskEvent{Source="Load",TaskId=i.ToString(),Title="Artifact",Status="succeeded",OpenPath=artifact});inbox.Drain();inbox.Drain();Check(hub.Snapshot().Length==50,"many output actions stay bounded and drain completely");Check(Program.Main(new[]{"--task-notice","--state-dir",root,"--source","CLI","--task-id","cli","--title","CLI fixture","--status","succeeded"})==0,"CLI enqueue returns before app startup");Check(inbox.Drain()==1,"CLI event readable by inbox");Check(Program.Main(new[]{"--task-notice","--state-dir",root,"--source","CLI","--task-id","literal","--title","--state-dir","--status","succeeded"})==0&&inbox.Drain()==1,"CLI literal option title cannot redirect state root");Store.Root=Path.GetDirectoryName(root);}
 static void Performance(){var c=new Config();for(int bits=0;bits<32;bits++){bool hidden=(bits&1)>0,sleep=(bits&2)>0,moving=(bits&4)>0,hover=(bits&8)>0,save=(bits&16)>0;c.ResourceSaving=save;Check(PerformanceRules.Frame(c,false,hidden,false,sleep,moving,hover)==PolishRules.FrameInterval(save,hidden,sleep,moving,hover),"legacy frame policy "+bits);}c.ResourceSaving=true;Check(PerformanceRules.MusicPoll(c,false,true,false,0)==4,"legacy hidden music polling preserved");foreach(string mode in CompanionOptions.Profiles){c.PerformanceProfile=mode;Check(PerformanceRules.Frame(c,false,true,true,false,true,true)>=500,"hidden/locked throttling "+mode);Check(PerformanceRules.MusicPoll(c,false,false,false,0)==.85,"visible music position cadence "+mode);}c.PerformanceProfile="smooth";c.BatterySaving=true;Check(PerformanceRules.Effective(c,true)=="quiet"&&PerformanceRules.Frame(c,true,false,false,false,true,false)==50,"battery profile temporary quiet override");Check(PerformanceRules.Effective(c,false)=="smooth","power restore retains selected profile");Check(PerformanceRules.MusicPoll(c,false,false,false,20)<=30&&PerformanceRules.MusicPoll(c,false,false,false,20)>.85,"failed connection retry capped");}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);try{Music();Scenes();Focus();Sharing();Inbox();Performance();}catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});return 1;}
  Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,SleepSchedule=false,IdleSleep=false,NoticeSound=false,LaunchChatGPTOnStart=false,LaunchMusicOnStart=false});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;pet.Loaded+=async delegate{try{await Task.Delay(1150);((DispatcherTimer)F(pet,"animation")).Stop();var w=app.Windows.OfType<SettingsWindow>().Single();var tabs=(TabControl)F(w,"settingsTabs");Check(tabs.Items.Cast<TabItem>().Any(t=>(string)t.Header=="专注与休息"),"focus page in navigation");pet.Settings.MusicEnabled=true;pet.Music.Current=new MusicState{Connected=true,Playing=true,Id="123",Title="状态演示（模拟歌曲）",Artist="隔离测试",Label="系统媒体已连接（模拟歌曲）",HasPosition=false,ConnectionSource="system"};w.NavigateCategory("音乐","");await Task.Delay(80);w.UpdateStatus();var text=(TextBlock)F(w,"musicActivityText");Check(text.IsVisible&&text.Text.Contains("当前动作")&&text.Text.Contains("副歌状态")&&text.Text.Contains("切换说明"),"music status card visible on first screen");Check(text.Text.Contains("缺少有效进度"),"missing progress visible in actual settings");w.Capture(Path.Combine(Store.Root,"music-status.png"));w.NavigateCategory("专注与休息","");pet.StartFocus(false);w.UpdateStatus();Check(pet.FocusRunning&&pet.FocusQuietActive&&pet.FocusStatus.Contains("25:00"),"focus starts via runtime with quiet overlay");pet.PauseFocus();w.UpdateStatus();Check(pet.FocusCanResume&&!pet.FocusRunning,"pause/continue runtime controls");w.Capture(Path.Combine(Store.Root,"focus.png"));pet.ResumeFocus();pet.ResetFocus();Check(!pet.FocusRunning&&!pet.FocusQuietActive,"ending focus restores walking eligibility");w.NavigateCategory("场景与维护","自动场景");await Task.Delay(80);Check(((ListBox)F(w,"autoRuleList")).IsVisible,"search expands automatic scene rules");w.NavigateCategory("通知中心","外部");await Task.Delay(80);Check(SettingsWindow.Descendants<CheckBox>(w).Any(b=>(string)b.Content=="启用外部脚本任务接收"&&b.IsVisible),"external inbox controls grouped under notices");Check(pet.Settings.GPTConnectionMode=="cdp"&&pet.Settings.MusicConnectionMode=="cdp"&&!pet.Settings.AutoScenesEnabled&&!pet.Settings.ExternalNoticesEnabled,"new optional features preserve original connection modes");
   var automatic=(SceneAutomation)F(pet,"autoScenes");pet.Settings.AutoScenesEnabled=true;bool baseHover=pet.Settings.MusicHoverOnly;automatic.Resume();automatic.Tick(pet.Settings,"休闲",0);automatic.Tick(pet.Settings,"休闲",3);pet.Save();Check(Store.Load().MusicHoverOnly==baseHover,"runtime save excludes automatic overlay");automatic.Clear(pet.Settings);pet.Settings.AutoScenesEnabled=false;
   pet.Settings.FocusReminder="badge";pet.StartFocus(false);var focus=(FocusClock)F(pet,"focusClock");focus.Session.Remaining=.01;var watch=(System.Diagnostics.Stopwatch)F(pet,"clock");Call(pet,"TickCompanionFeatures",watch.Elapsed.TotalSeconds+1);Check(pet.TaskNotices.Snapshot().Any(n=>n.Source=="专注计时"&&n.Status=="waiting")&&!pet.FocusRunning,"focus completion integrates with notification center");pet.StartFocus(false);Call(pet,"PauseFocusForSystem");Check(!pet.FocusRunning&&File.Exists(Path.Combine(Store.Root,"focus-session.json")),"system suspension persists paused focus state");pet.ResetFocus();pet.PauseAutoScenes();pet.Save();Check(Store.Load().AutoScenesPaused,"manual scene pause persists across restart");pet.ResumeAutoScenes();Check(!Store.Load().AutoScenesPaused,"manual resume persists across restart");
   string shared=Path.Combine(Store.Root,"ui-shared.json");var outgoing=pet.PersistentPreferences();outgoing.Theme="dark";outgoing.Size=200;var incoming=SharedPreferences.Publish(shared,outgoing,null);var review=new SharedPreferenceReviewWindow(pet,shared,incoming){Owner=w};var choices=(Dictionary<string,CheckBox>)F(review,"choices");Check(choices.ContainsKey("Theme")&&choices.ContainsKey("Size"),"shared diff offers individual preference choices");var applyTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(80)};applyTimer.Tick+=delegate{applyTimer.Stop();choices["Size"].IsChecked=false;Call(review,"Apply");};applyTimer.Start();Check(review.ShowDialog()==true&&pet.Settings.Theme=="dark"&&pet.Settings.Size!=200,"selective shared application changes only checked values");Check(Directory.GetFiles(Path.Combine(Store.Root,"preference-backups"),"*.json").Length>0,"shared application creates recoverable backup");w.RefreshTheme();Check(((System.Windows.Media.SolidColorBrush)((TextBlock)F(w,"musicActivityText")).Foreground).Color==PetPalette.Ink,"live status follows light/dark theme changes");
   w.NavigateCategory("专注与休息","");w.Width=760;w.Height=540;await Task.Delay(100);w.Capture(Path.Combine(Store.Root,"focus-small.png"));w.Close();passed=true;}catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{Store.Atomic("result.json",new{passed,checks,names});foreach(var window in app.Windows.Cast<Window>().Where(window=>window!=pet).ToArray())window.Close();pet.Close();}};app.Run(pet);return passed?0:1;
